using System;using System.Data;using System.Drawing;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms { public class FrmRegistrationStatus:StyledForm { public FrmRegistrationStatus(){Text="Registration Status";Size=new Size(700,380);StartPosition=FormStartPosition.CenterParent;var input=new TextBox{Width=240};var result=new DataGridView{Dock=DockStyle.Bottom,Height=260,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};var p=new FlowLayoutPanel{Dock=DockStyle.Top,Height=70,Padding=new Padding(15)};p.Controls.Add(new Label{Text="Application Number",AutoSize=true,Margin=new Padding(3,9,3,3)});p.Controls.Add(input);var b=new Button{Text="Check Status"};p.Controls.Add(b);b.Click+=delegate{var t=QueryUtil.Table("SELECT A.ApplicationNo,S.StudentName,A.[Year],A.Status,A.SubmittedDate,A.LastUpdated,A.CorrectionReason,A.RejectReason,P.PaymentStatus FROM (Applications A INNER JOIN Students S ON A.StudentId=S.StudentId) LEFT JOIN Payments P ON A.ApplicationId=P.ApplicationId WHERE A.ApplicationNo=?",input.Text.Trim());result.DataSource=t;if(t.Rows.Count==0)MessageBox.Show("Application not found.");};Controls.Add(result);Controls.Add(p);} } }
